insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('store-logos','store-logos',false,4194304,array['image/jpeg','image/png','image/webp']),('menu-images','menu-images',false,4194304,array['image/jpeg','image/png','image/webp']),('conversation-media','conversation-media',false,20971520,array['image/jpeg','image/png','image/webp','audio/ogg','audio/mpeg','audio/mp4','audio/webm','video/mp4','video/webm','application/pdf']) on conflict(id) do nothing;
create policy pedizza_files_read on storage.objects for select to authenticated using(bucket_id in ('store-logos','menu-images','conversation-media') and (storage.foldername(name))[1] ~ '^[0-9a-f-]{36}$' and private.subscription_active(((storage.foldername(name))[1])::uuid) and private.has_permission(((storage.foldername(name))[1])::uuid,case bucket_id when 'store-logos' then 'settings.view' when 'menu-images' then 'menu.view' else 'conversations.view' end));
-- Uploads are accepted by server-validated, narrowly scoped paths; no browser write grants.
